SourceCode.Declaration:
/// <summary>
/// The <c>AVATonnageController</c> class is the controller class for <c>Tonnage</c>
/// </summary>
class AVATonnageController extends SysOperationServiceController
{
}

Method.Source:
/// <summary>
///    AVA <c>new</c> method.
/// </summary>
protected void new()
{
    super();

    this.parmClassName(classStr(AVATonnageService));
    this.parmMethodName(methodStr(AVATonnageService, runService));
}

/// <summary>
///    AVA <c>newFromArgs</c> method.
/// </summary>
/// <param name="_args">
///    <c>Args</c> as type
/// </param>
/// <returns>
///    <c>AVATonnageController</c> as return value
/// </returns>
public static AVATonnageController newFromArgs(Args _args)
{
    AVATonnageController controller;

    controller = new AVATonnageController();
    controller.parmArgs(_args);
    controller.parmLoadFromSysLastValue(false);
    //controller.parmShowDialog(false);

    return controller;
}

/// <summary>
///    AVA <c>main</c> method.
/// </summary>
/// <param name="_args">
///    <c>Args</c> as type
/// </param>
public static void main(Args _args)
{
    AVATonnageController        controller;
    AVATonnageContract          dataContract;
    SysOperationStartResult     sysOperationStartResult;

    Common                      locCommon;

    KCS_TonnageSetup            locKCS_TonnageSetup;
    KCS_TonnageCalcedData       locKCS_TonnageCalcedData;
    date                        locToday;

    if (!_args)
    {
        throw error("@SYS25407");
    }

    locKCS_TonnageSetup = KCS_TonnageSetup::find();

    controller      = AVATonnageController::newFromArgs(_args);
    controller.parmExecutionMode(SysOperationExecutionMode::Synchronous);

    dataContract    = controller.getDataContractObject();
    dataContract.parmAutomaticMode(true);
    dataContract.parmTonnageDaysForwardCalculation(locKCS_TonnageSetup.Days);
    dataContract.parmTonnagePercentageWarning(locKCS_TonnageSetup.PercentWarning);
    locToday = DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone());
    dataContract.parmStartDate(locToday);
    dataContract.parmEndDate(locToday + locKCS_TonnageSetup.Days);
    dataContract.parmInventSiteId('');

    if (_args && _args.record())
    {
        locCommon = _args.record();
        if(locCommon.RecId && locCommon.TableId == tableNum(KCS_TonnageCalcedData))
        {
            locKCS_TonnageCalcedData = locCommon;

            dataContract.parmArgs(_args);
        }

    }

    sysOperationStartResult = controller.startOperation();

    if(sysOperationStartResult == SysOperationStartResult::Started)
    {
        info(strFmt("@SYS82282", "@NDX:NXAOperationStarted"));
    }
}
